{
  "understanding": {
    "purpose": "比较六个重点城市四个季度的GDP增速，并结合说明理解各城市的变化背景。",
    "reading": "读者先按行查看同一城市的季度变化，也会沿季度列比较城市；说明文字提供背景，通常在数值比较之后阅读。",
    "groups": [
      "第一列城市名称是行标识，应与同一行的数值和说明保持清晰对应。",
      "第二至第五列都是季度增速，作用相同，应保持一致的宽度和节奏，方便横向及纵向比较。",
      "第六列说明是较长的连续文字，需要更多宽度，并可利用数据行的高度自然换行。"
    ],
    "keep_intact": [
      "城市名称和季度增速数值应保持完整，不拆分。",
      "尽量保持各季度子表头完整；总表头应清楚覆盖四个季度列。"
    ],
    "may_wrap": [
      "说明文字可按中文语义自然换行；各行已有的说明换行高度可容纳其他单元格的换行。",
      "在优先为说明分配空间的方案中，季度子表头可以换行，但会增加表头高度。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [55, 67, 67, 67, 67, 396],
      "idea": "季度表头恰好保持单行，并将大部分剩余宽度给说明，在数值比较与说明阅读之间取得平衡。"
    },
    {
      "name": "B",
      "widths": [59, 80, 80, 80, 80, 340],
      "idea": "加宽城市和季度列，形成更从容的比较节奏，代价是说明文字需要更多行。"
    },
    {
      "name": "C",
      "widths": [52, 62, 62, 62, 62, 419],
      "idea": "优先扩大说明列，以减少长段文字换行，同时接受四个季度子表头换行。"
    }
  ]
}
